insert into public.site_settings (key, value) values
  ('company', '{"name":"ADS Global","legalName":"ADS Global Limited","tagline":"Connect Globally, Trade with Confidence.","positioning":"Global Trade Solutions","shortDescription":"A diversified international trading house for import and export, sourcing, logistics and trade consulting, headquartered in Shenyang, China, with operations in Nigeria.","claimsMode":"flag"}'::jsonb),
  ('about', '{"story":["ADS Global Limited is a diversified international trading house with operations spanning food and beverages, import and export, technology, machinery and strategic consulting.","Headquartered in Shenyang, China, with a branch in Shandong and offices in Abuja and Kano, Nigeria, we use our presence in both markets to source quality products and deliver practical trade solutions across continents."],"mission":"Facilitate seamless global trade through quality products, reliable logistics, and expert consulting that empowers our partners to succeed across borders.","vision":"Become a leading international trading house known for integrity, innovation, and sustainable value creation in the global marketplace.","alternateMission":"To revolutionize global trade by connecting markets, streamlining supply chains, and delivering exceptional value through innovative solutions and unwavering commitment to quality.","alternateVision":"To be the world''s most trusted partner in international trade, recognized for our integrity, expertise, and ability to bridge markets while fostering sustainable economic growth.","missionVisionConfirmed":false,"values":[{"title":"Integrity","description":"Building trust through transparency and ethical business practices in every transaction."},{"title":"Excellence","description":"Commitment to the highest standards of quality, service and professional conduct."},{"title":"Global Collaboration","description":"Fostering partnerships and connections across cultures and continents."},{"title":"Customer Success","description":"Delivering solutions that drive growth and profitability for our clients."}]}'::jsonb),
  ('contact', '{"generalEmail":"globalltdads@gmail.com","partnersEmail":"globalltdads@gmail.com","website":"https://www.adsglobaltd.com","primaryPhone":"+8618012824844","defaultOfficeSlug":"shenyang"}'::jsonb),
  ('socials', '{"linkedin":null,"x":null,"facebook":null,"instagram":null}'::jsonb),
  ('hero', '{"eyebrow":"Global Trade Solutions","headlineLine1":"Connect globally.","headlineLine2":"Trade with confidence.","subhead":"Import, export, sourcing, logistics and trade consulting across 14 product categories, with teams in China and Nigeria.","imageUrl":"https://images.pexels.com/photos/5221699/pexels-photo-5221699.jpeg?auto=compress&cs=tinysrgb&w=2400","imageAlt":"Gantry cranes over a container terminal in the harbour at night","videoUrl":null}'::jsonb)
