  ('shenyang', 'Shenyang head office', 'Shenyang Sadiq International Trade Co., Ltd.', null, 'China', 'CN', 'Shenyang', 'Room 3, No. 703, West Five District, 888 Puhe Avenue, Shenbei New District, Shenyang, Liaoning Province, China', true, '+8618012824844', '+8613591479952', 'globalltdads@gmail.com', 'Asia/Shanghai', 'CST', 'UTC+8', true, 'https://www.google.com/maps/search/?api=1&query=888%20Puhe%20Avenue%2C%20Shenbei%20New%20District%2C%20Shenyang%2C%20Liaoning%2C%20China', '[{"days":"Mon–Fri","opens":"09:00","closes":"18:00"},{"days":"Saturday","opens":"10:00","closes":"16:00","note":"[CONFIRM: which time zone]"},{"days":"Sunday","opens":null,"closes":null}]'::jsonb, false, 1),
