  ('abuja', 'Abuja office', 'Abubakar Dahiru Sadiq Global Ltd.', 'RC 8079004', 'Nigeria', 'NG', 'Abuja', 'Plot 458 Ahmadu Bello Way, opposite Access Bank, Garki II, Abuja, Nigeria', true, '+2347031129111', '+8613591479952', 'globalltdads@gmail.com', 'Africa/Lagos', 'WAT', 'UTC+1', false, 'https://www.google.com/maps/search/?api=1&query=Plot%20458%20Ahmadu%20Bello%20Way%2C%20Garki%20II%2C%20Abuja%2C%20Nigeria', '[{"days":"Mon–Fri","opens":"09:00","closes":"18:00"},{"days":"Saturday","opens":"10:00","closes":"16:00","note":"[CONFIRM: which time zone]"},{"days":"Sunday","opens":null,"closes":null}]'::jsonb, false, 3),
  ('kano', 'Kano office', 'Abubakar Dahiru Sadiq Global Ltd.', 'RC 8079004', 'Nigeria', 'NG', 'Kano', 'No. 86 U/Badawa, A.A. Rano Street, Hotoro NNPC Depot, Maiduguri Road, Kano, Nigeria', true, '+2347031129111', '+8613591479952', 'globalltdads@gmail.com', 'Africa/Lagos', 'WAT', 'UTC+1', false, 'https://www.google.com/maps/search/?api=1&query=Hotoro%20NNPC%20Depot%2C%20Maiduguri%20Road%2C%20Kano%2C%20Nigeria', '[{"days":"Mon–Fri","opens":"09:00","closes":"18:00"},{"days":"Saturday","opens":"10:00","closes":"16:00","note":"[CONFIRM: which time zone]"},{"days":"Sunday","opens":null,"closes":null}]'::jsonb, false, 4)
insert into public.categories (slug, name, hs_label, category_group, summary, description, example_products, example_products_confirmed, sourcing_regions, sourcing_regions_confirmed, incoterms, image_url, image_alt, image_is_stock, sort_order, published) values
  ('food-beverages', 'Food & Beverages', 'HS 01–24', 'consumer', 'Premium sourcing of food and beverage products from global suppliers.', 'We source packaged foods, ingredients and beverages from vetted producers, with attention to shelf life, labelling and import permits for the destination market.', array['Rice, pasta and grains', 'Edible oils', 'Canned and packaged foods', 'Beverages and juices', 'Confectionery']::text[], false, array['China', 'Southeast Asia', 'Global']::text[], false, array['EXW', 'FOB', 'CFR', 'CIF', 'DAP', 'DDP']::text[], 'https://images.pexels.com/photos/33975355/pexels-photo-33975355.jpeg?auto=compress&cs=tinysrgb&w=1600', 'Colourful fresh produce on display in a grocery store', true, 1, true),
  ('import-export-services', 'Import & Export Services', 'SVC · Trade', 'services', 'Comprehensive import and export logistics solutions.', 'End-to-end handling of cross-border shipments: supplier payments coordination, export documentation, freight booking, insurance and customs clearance support.', array['Freight booking (sea, air, road)', 'Export documentation', 'Cargo insurance arrangement', 'Customs clearance support', 'Consolidation (LCL)']::text[], false, array['China ⇄ West Africa', 'Global trade lanes']::text[], false, array['EXW', 'FOB', 'CIF', 'DAP', 'DDP']::text[], 'https://images.pexels.com/photos/28438334/pexels-photo-28438334.jpeg?auto=compress&cs=tinysrgb&w=1600', 'Container terminal with straddle carriers moving boxes', true, 2, true),
  ('office-supplies', 'Office Supplies', 'HS 48 · 96', 'consumer', 'Complete office supply solutions for businesses of all sizes.', 'Stationery, paper products and office equipment sourced in bulk for corporate, education and government buyers.', array['Copy paper and notebooks', 'Pens and writing instruments', 'Files and folders', 'Office furniture', 'Printers and consumables']::text[], false, array['China']::text[], false, array['EXW', 'FOB', 'CFR', 'CIF', 'DAP', 'DDP']::text[], 'https://images.pexels.com/photos/7718714/pexels-photo-7718714.jpeg?auto=compress&cs=tinysrgb&w=1600', 'Flat lay of office stationery: notebooks, pens and clips', true, 3, true),
  ('apparel-fashion', 'Apparel & Fashion', 'HS 61–64', 'consumer', 'Quality fashion and apparel procurement and distribution.', 'Garments, uniforms, footwear and textiles from established mills and factories, with size-set approval and pre-shipment checks.', array['Ready-to-wear garments', 'Workwear and uniforms', 'Footwear', 'Fabrics and textiles', 'Bags']::text[], false, array['China', 'Southeast Asia']::text[], false, array['EXW', 'FOB', 'CFR', 'CIF', 'DAP', 'DDP']::text[], 'https://images.pexels.com/photos/3812433/pexels-photo-3812433.jpeg?auto=compress&cs=tinysrgb&w=1600', 'Garments on hangers along clothing racks', true, 4, true),
  ('technology-electronics', 'Technology & Electronics', 'HS 85 · 8471', 'consumer', 'Latest technology and electronic products from trusted manufacturers.', 'Consumer and business electronics, components and accessories from certified manufacturers, with attention to voltage, plug type and certification requirements for the destination.', array['Laptops and computer accessories', 'Mobile phones and accessories', 'Solar panels, inverters and batteries', 'CCTV and networking equipment', 'Electronic components']::text[], false, array['China (Guangdong)', 'Asia']::text[], false, array['EXW', 'FOB', 'CFR', 'CIF', 'DAP', 'DDP']::text[], 'https://images.pexels.com/photos/1010485/pexels-photo-1010485.jpeg?auto=compress&cs=tinysrgb&w=1600', 'Close-up of a green electronic circuit board', true, 5, true),
  ('machinery-equipment', 'Machinery & Equipment', 'HS 84', 'industrial', 'Industrial machinery and equipment for manufacturing operations.', 'Production lines, processing machinery, generators and spare parts, sourced with technical specification review and factory acceptance checks.', array['Food-processing machinery', 'Packaging machines', 'Generators', 'Construction equipment', 'Spare parts']::text[], false, array['China (Liaoning, Jiangsu, Zhejiang)']::text[], false, array['EXW', 'FOB', 'CFR', 'CIF', 'DAP', 'DDP']::text[], 'https://images.pexels.com/photos/12951623/pexels-photo-12951623.jpeg?auto=compress&cs=tinysrgb&w=1600', 'Heavy industrial machinery in a plant', true, 6, true),
  ('building-materials', 'Building Materials', 'HS 68–70 · 72–73', 'industrial', 'High-quality building materials and construction supplies.', 'Tiles, sanitary ware, steel products, roofing and finishing materials for contractors and developers, consolidated into full containers.', array['Floor and wall tiles', 'Sanitary ware', 'Steel sections and rebar', 'Roofing sheets', 'Doors, windows and fittings']::text[], false, array['China']::text[], false, array['EXW', 'FOB', 'CFR', 'CIF', 'DAP', 'DDP']::text[], 'https://images.pexels.com/photos/31763543/pexels-photo-31763543.jpeg?auto=compress&cs=tinysrgb&w=1600', 'Roof tiles stacked on a pallet at a building site', true, 7, true),
  ('specialty-chemicals', 'Specialty Chemicals', 'HS 28–38', 'industrial', 'Industrial and specialty chemicals for various applications.', 'Industrial and specialty chemicals supplied with safety data sheets and the correct dangerous-goods documentation where required.', array['Water-treatment chemicals', 'Coatings and additives', 'Industrial cleaning agents', 'Raw materials for manufacturing']::text[], false, array['China']::text[], false, array['FOB', 'CFR', 'CIF', 'DAP']::text[], 'https://images.pexels.com/photos/1146627/pexels-photo-1146627.jpeg?auto=compress&cs=tinysrgb&w=1600', 'Clear laboratory glassware on a bench', true, 8, true),
  ('transportation-equipment', 'Transportation Equipment', 'HS 86–89', 'automotive_transport', 'Vehicles and transportation solutions for logistics.', 'Commercial vehicles, trailers and fleet equipment for logistics operators, shipped RoRo or in flat-rack containers.', array['Trailers and semi-trailers', 'Tankers', 'Forklifts', 'Buses', 'Fleet spare parts']::text[], false, array['China']::text[], false, array['FOB', 'CFR', 'CIF', 'DAP']::text[], 'https://images.pexels.com/photos/2348359/pexels-photo-2348359.jpeg?auto=compress&cs=tinysrgb&w=1600', 'Row of parked trucks under a cloudy sky', true, 9, true),
  ('jewelry-accessories', 'Jewelry & Accessories', 'HS 71 · 42', 'consumer', 'Fine jewelry and luxury accessories sourcing and distribution.', 'Jewellery, watches and fashion accessories, sourced in retail-ready packaging with batch quality checks.', array['Fashion jewellery', 'Watches', 'Handbags and leather goods', 'Hair accessories', 'Sunglasses']::text[], false, array['China (Guangdong, Zhejiang)']::text[], false, array['EXW', 'FOB', 'CIF', 'DDP']::text[], 'https://images.pexels.com/photos/20858959/pexels-photo-20858959.jpeg?auto=compress&cs=tinysrgb&w=1600', 'Jewellery arranged in a display case', true, 10, true),
  ('home-appliances', 'Home Appliances', 'HS 8418 · 8450 · 8516', 'consumer', 'Quality home appliances from leading global manufacturers.', 'Large and small appliances specified for the destination grid, with spare-parts and warranty arrangements agreed up front.', array['Refrigerators and freezers', 'Washing machines', 'Air conditioners', 'Cookers and microwaves', 'Small kitchen appliances']::text[], false, array['China']::text[], false, array['EXW', 'FOB', 'CFR', 'CIF', 'DAP', 'DDP']::text[], 'https://images.pexels.com/photos/5825422/pexels-photo-5825422.jpeg?auto=compress&cs=tinysrgb&w=1600', 'Kitchen fitted with modern home appliances', true, 11, true),
  ('fmcg', 'Daily-use Goods (FMCG)', 'HS 33 · 34 · 96', 'consumer', 'Fast-moving consumer goods and household products.', 'Household, personal-care and cleaning products for distributors and retailers, with labelling adapted to the destination market.', array['Personal-care products', 'Detergents and cleaning products', 'Tissue and paper goods', 'Plasticware and kitchenware', 'Baby care']::text[], false, array['China', 'Asia']::text[], false, array['EXW', 'FOB', 'CFR', 'CIF', 'DAP', 'DDP']::text[], 'https://images.pexels.com/photos/1366594/pexels-photo-1366594.jpeg?auto=compress&cs=tinysrgb&w=1600', 'Store shelves stocked with household products', true, 12, true),
  ('information-consulting', 'Information Consulting', 'SVC · Advisory', 'services', 'Market research and business consulting services.', 'Market-entry research, supplier due diligence and trade advisory for companies buying from or selling into China and West Africa.', array['Market-entry research', 'Supplier due diligence', 'Import regulation guidance', 'Trade-fair and factory visit support']::text[], false, array['China', 'Nigeria', 'West Africa']::text[], false, '{}'::text[], 'https://images.pexels.com/photos/8145328/pexels-photo-8145328.jpeg?auto=compress&cs=tinysrgb&w=1600', 'Team reviewing charts and data on laptops', true, 13, true),
  ('automobiles', 'Automobiles', 'HS 87', 'automotive_transport', 'Trucks, EVs, luxury cars and automotive solutions.', 'Passenger cars, electric vehicles and trucks sourced to the destination''s import rules, shipped RoRo or containerised.', array['Electric vehicles (EVs)', 'Trucks and tippers', 'SUVs and passenger cars', 'Luxury vehicles', 'Automotive parts']::text[], false, array['China']::text[], false, array['FOB', 'CFR', 'CIF', 'DAP']::text[], 'https://images.pexels.com/photos/29566904/pexels-photo-29566904.jpeg?auto=compress&cs=tinysrgb&w=1600', 'Line of new electric cars in a parking lot', true, 14, true)
insert into public.stats (key, label, value, prefix, suffix, confirmed, note, sort_order) values
  ('categories', 'Product & service categories', 14, '', '', true, 'Matches the 14 categories listed on the site.', 1),
  ('offices', 'Offices in China and Nigeria', 4, '', '', true, 'Shenyang, Shandong (Liangshan), Abuja, Kano — per company letterheads.', 2),
  ('countries', 'Countries served', 50, '', '+', false, '[CONFIRM] Old site: ''50+ countries served''.', 3),
  ('partners', 'Global partners', 1000, '', '+', false, '[CONFIRM] Old site: ''1000+ global partners''.', 4),
  ('years', 'Years of experience', 10, '', '+', false, '[CONFIRM] Old site: ''10+ years experience''. Conflicts with ''decades of experience'' in Strengths.', 5),
  ('supply_connections', 'Supply connections', 100, '', '%', false, '[CONFIRM] Old site: ''100% supply connections''. Unclear what this measures — recommend removing.', 6)
insert into public.claims (key, label, text, source, confirmed, note) values
  ('iso_status', 'ISO status', 'ISO-certified quality control processes', 'About: ''ISO-certified quality control processes'' vs Strengths: ''ISO-aligned quality standards''.', false, '[CONFIRM] Certified (which standard, e.g. ISO 9001:2015, certificate number, certifying body) or only aligned?'),
  ('support_247', '24/7 support', '24/7 global hotline for urgent shipment issues', 'Contact: ''24/7 Global Hotline'', ''Emergency Support''; Hero: ''24/7 Support''; hours: ''Sunday — Emergency Only''.', false, '[CONFIRM] Is a 24/7 line actually staffed? Which number?'),
  ('team_experience', 'Team experience', 'A multidisciplinary team with decades of combined international trade experience', 'Strengths: ''decades of international trade experience'' vs About: ''Industry veterans with 10+ years experience''.', false, '[CONFIRM] Which is correct?'),
  ('supplier_network', 'Supplier network reach', 'Supplier connections across Africa, Asia and worldwide', 'Strengths: ''Established connections across Africa, Asia, and worldwide supplier network''.', false, '[CONFIRM] Keep as worded?')
insert into public.strengths (slug, title, description, icon, sort_order) values
  ('portfolio', 'Extensive product portfolio', 'Access to 14 major product and service categories spanning food, technology, machinery and more.', 'LayoutGrid', 1),
  ('quality', 'Quality assurance', 'Defined quality standards and inspection protocols before goods leave the factory.', 'BadgeCheck', 2),
  ('network', 'Global supply-chain network', 'Supplier and logistics relationships linking Asian manufacturers with buyers in Africa and beyond.', 'Network', 3),
  ('team', 'Expert team', 'A multidisciplinary team covering sourcing, inspection, shipping and customs on both sides of the trade lane.', 'Users', 4),
  ('customer', 'Customer-centric service', 'Dedicated support and tailored solutions for each client partnership.', 'Handshake', 5)
insert into public.process_steps (slug, title, description, details, image_url, image_alt, sort_order) values
  ('enquiry', 'Enquiry', 'Tell us what you need: product, specification, quantity, destination and timeline.', array['Request a quote online or by email', 'We confirm the brief within one business day [CONFIRM]', 'NDA available on request [CONFIRM]']::text[], 'https://images.pexels.com/photos/8428059/pexels-photo-8428059.jpeg?auto=compress&cs=tinysrgb&w=1600', 'Two business people agreeing a deal with a handshake', 1),
  ('sourcing-quotation', 'Sourcing & quotation', 'We shortlist vetted manufacturers, compare samples and send a quotation on your chosen Incoterm.', array['Supplier shortlisting and factory checks', 'Samples where needed', 'Quotation on EXW, FOB, CIF or DDP terms']::text[], 'https://images.pexels.com/photos/31047132/pexels-photo-31047132.jpeg?auto=compress&cs=tinysrgb&w=1600', 'Factory floor with workers at production stations', 2),
  ('quality-inspection', 'Quality inspection', 'Goods are checked against your specification before they leave the factory.', array['Pre-shipment inspection', 'Photo and video reports', 'Third-party inspection on request']::text[], 'https://images.pexels.com/photos/7937365/pexels-photo-7937365.jpeg?auto=compress&cs=tinysrgb&w=1600', 'Inspector in a safety helmet checking goods', 3),
  ('shipping-customs', 'Shipping & customs', 'We book freight, prepare export documents and coordinate clearance at the destination port.', array['Sea FCL (20ft / 40ft / 40HC) and LCL, air and road', 'Commercial invoice, packing list, bill of lading, certificate of origin', 'Customs clearance support at destination']::text[], 'https://images.pexels.com/photos/16053939/pexels-photo-16053939.jpeg?auto=compress&cs=tinysrgb&w=1600', 'Workers loading cargo into a shipping container at a port', 4),
  ('delivery-after-sales', 'Delivery & after-sales', 'Final-mile delivery to your warehouse or site, with follow-up on any claims or reorders.', array['Door delivery where available', 'Shipment tracking updates', 'Reorders and claims handled by one contact']::text[], 'https://images.pexels.com/photos/14005602/pexels-photo-14005602.jpeg?auto=compress&cs=tinysrgb&w=1600', 'Cargo truck travelling on a highway', 5)
